/* CACAO NOTE mascots: 4 wandering companions, with no dependencies or user-data collection.
   Page-anchored inhabitants only. Existing forms, QR, passwords and delete functionality are untouched. */
(() => {
  'use strict';
  if (document.documentElement.dataset.cnPets === 'on') return;
  if (/^\/admin(?:\/|$)/i.test(location.pathname)) return;
  document.documentElement.dataset.cnPets = 'on';
  document.documentElement.dataset.cnPetsVersion = '24';
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const mobile = () => matchMedia('(max-width: 650px)').matches;
  const r = (min,max) => Math.random() * (max - min) + min;
  const pick = arr => arr[Math.floor(Math.random() * arr.length)];
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const CN_SPRITES={"white-0":"data:image/webp;base64,","white-1":"data:image/webp;base64,","white-2":"data:image/webp;base64,","white-3":"data:image/webp;base64,","white-4":"data:image/webp;base64,","black-0":"data:image/webp;base64,","black-1":"data:image/webp;base64,","black-2":"data:image/webp;base64,","black-3":"data:image/webp;base64,","black-4":"data:image/webp;base64,","panda-0":"data:image/webp;base64,","panda-1":"data:image/webp;base64,","panda-2":"data:image/webp;base64,","panda-3":"data:image/webp;base64,","panda-4":"data:image/webp;base64,","duck-0":"data:image/webp;base64,","duck-1":"data:image/webp;base64,","duck-2":"data:image/webp;base64,","duck-3":"data:image/webp;base64,","duck-4":"data:image/webp;base64,"};
  const src=(id,frame)=>CN_SPRITES[`${id}-${frame}`];

  // V24: the duck's real closed-eye illustration, reclined using the SAME original drawing.
  const CN_DUCK_SLEEP = 'data:image/webp;base64,';
  const sleepFrame = {white:4,black:4,panda:2,duck:2};
  const information = [
    {id:'white',name:'Mèo trắng',pose:0,rest:[0,1,2,3,4],says:['Tui buồn ngủ quá…','Gửi ai vậy?','Gửi cho bản thân cũng được mà.','Cho tui ngủ thêm chút…','Tui không đọc trộm đâu.']},
    {id:'black',name:'Mèo đen',pose:2,rest:[0,2,3,4],says:['Tui thấy bạn bấm rồi nha!','Bắt được con trỏ chưa?','Cho tui chạy thêm vòng nữa!','Có gì vui thế?','Nhìn tui nè!']},
    {id:'panda',name:'Gấu trúc',pose:0,rest:[0,1,2,3,4],says:['Từ từ thôi…','Để tui ngồi đây xíu.','Tui lăn một vòng nha?','Có bánh không?','Một lời nhắn nhỏ cũng vui.']},
    {id:'duck',name:'Vịt vàng',pose:0,rest:[0,1,2,3,4],says:['Gửi ai vậy?!','Đừng bấm đầu tui!','Tui có giận đâu!!','Đi đâu cũng gặp bạn vậy!','Đó, thấy chưa!']}
  ];
  const customActions = {
    white:[{frame:1,motion:'sleep',dur:2100},{frame:2,motion:'hop',dur:1050},{frame:3,motion:'shake',dur:900},{frame:4,motion:'roll',dur:1600}],
    black:[{frame:0,motion:'peek',dur:1150},{frame:3,motion:'hop',dur:1000},{frame:4,motion:'roll',dur:1500},{frame:2,motion:'stomp',dur:900}],
    panda:[{frame:1,motion:'hop',dur:1150},{frame:2,motion:'sleep',dur:2300},{frame:3,motion:'roll',dur:1450},{frame:4,motion:'sleep',dur:1800}],
    duck:[{frame:1,motion:'stomp',dur:1200},{frame:2,motion:'shake',dur:1100},{frame:3,motion:'run',dur:1000},{frame:4,motion:'stomp',dur:1100}]
  };



  /* CACAO NOTE — inhabitants belong to the document world, never to the viewport. */
  const main = document.querySelector('main');
  if (!main) return;

  /* V17 — real photos of the first finished CACAO NOTE handmade lip-balm batch.
     This enhances the existing product slot without changing QR or gift logic. */
  function installActualProductPhotos(){
    const placeholder=document.querySelector('.product-image-slot');
    if(!placeholder || document.querySelector('.cn-actual-product-gallery'))return;
    const photos=[
      {src:'data:image/png;base64,',alt:'Thỏi son dưỡng handmade đã mở nắp, được tách nền',caption:'Thỏi son dưỡng handmade đã mở nắp.'},
      {src:'data:image/png;base64,',alt:'Thỏi son dưỡng CACAO NOTE được đóng nắp',caption:'Thỏi son dưỡng đóng nắp, vỏ trắng tối giản.'},
      {src:'data:image/png;base64,',alt:'Thỏi son dưỡng handmade hoàn thành, góc nhìn chính diện',caption:'Một trong các thỏi son đã làm xong.'},
      {src:'data:image/png;base64,',alt:'Bề mặt son dưỡng nhìn từ trên xuống',caption:'Bề mặt son dưỡng nhìn từ trên xuống.'},
      {src:'data:image/png;base64,',alt:'Các thỏi son dưỡng vừa được làm và xếp thành hai hàng',caption:'Hình ảnh mẻ son dưỡng thực tế.'}
    ];
    const gallery=document.createElement('div');
    gallery.className='cn-actual-product-gallery';
    gallery.setAttribute('aria-label','Hình ảnh sản phẩm CACAO NOTE thật');
    gallery.innerHTML=`<div class="cn-actual-photo-top"><span>PRODUCT PHOTOGRAPHY / 2026</span><span>01 / 05</span></div>
      <figure class="cn-actual-photo-stage"><img loading="lazy" decoding="async" alt=""/><figcaption class="cn-actual-photo-caption"></figcaption></figure>
      <div class="cn-actual-photo-thumbnails" role="group" aria-label="Chọn ảnh sản phẩm"></div>
      <p class="cn-actual-photo-note">Hình từ ảnh sản phẩm handmade thực tế, đã tách nền và xử lý kỹ thuật số.</p>`;
    const image=gallery.querySelector('.cn-actual-photo-stage img');
    const caption=gallery.querySelector('.cn-actual-photo-caption');
    const count=gallery.querySelector('.cn-actual-photo-top span:last-child');
    const choices=gallery.querySelector('.cn-actual-photo-thumbnails');
    const buttons=[];
    photos.forEach((photo,index)=>{
      const button=document.createElement('button');
      button.type='button';
      button.className='cn-actual-photo-thumb';
      button.setAttribute('aria-label',`Xem ảnh sản phẩm ${index+1}`);
      button.setAttribute('aria-pressed','false');
      const thumb=document.createElement('img');
      thumb.src=photo.src;thumb.alt='';thumb.loading='lazy';thumb.decoding='async';
      button.append(thumb);
      button.addEventListener('click',()=>showPhoto(index));
      choices.append(button);buttons.push(button);
    });
    function showPhoto(index){
      const photo=photos[index];
      image.src=photo.src;image.alt=photo.alt;
      image.style.objectFit='contain';
      image.style.objectPosition='center';
      caption.textContent=photo.caption;
      count.textContent=`${String(index+1).padStart(2,'0')} / ${String(photos.length).padStart(2,'0')}`;
      buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));
    }
    placeholder.replaceWith(gallery);
    showPhoto(0);
    const note=document.querySelector('.product-note');
    if(note)note.textContent='Mẻ son dưỡng handmade đầu tiên đã được làm xong. Đây là sản phẩm mẫu phục vụ dự án học tập; thành phần, đặc tính và độ an toàn chưa được kiểm nghiệm chính thức.';
  }
  installActualProductPhotos();

  const world = document.createElement('div');
  world.className = 'cn-world';
  world.setAttribute('aria-label','Các bạn thú sống trong CACAO NOTE');
  main.append(world);

  const sections = [
    {key:'hero', sel:'#hero'}, {key:'product', sel:'#product'},
    {key:'gift',sel:'#gift-app'}, {key:'story',sel:'#about'},
    {key:'steps',sel:'#how'}, {key:'end',sel:'.end-banner'}
  ];
  const homeKeys = ['hero','product','gift','story'];
  const zoneMap = new Map();
  const rng = (a,b) => a + Math.random() * (b-a);
  const choose = arr => arr[Math.floor(Math.random()*arr.length)];
  // V15: fit the animal AND its collision rectangle inside the narrow mobile
  // side-lane. At 320–385px the original 52px footprint crossed the text
  // exclusion zone and disconnected the vertical track for three mascots.
  const petSize = () => innerWidth <= 385 ? 48 : innerWidth <= 650 ? 52 : 64;
  const prefersQuiet = matchMedia('(prefers-reduced-motion: reduce)').matches;
  let muted = true, hidden = false, audioCtx = null, globalBusy = false;
  let geometryTimer = 0;
  let lastFriendScene = 0;
  let ambienceStarted = false;
  let pendingGeometry = false;

  function audio(id) {
    if(muted) return;
    try {
      const Context = window.AudioContext || window.webkitAudioContext;
      if(!Context) return;
      audioCtx ??= new Context();
      if(audioCtx.state === 'suspended') audioCtx.resume().catch(()=>{});
      const start=audioCtx.currentTime;
      const notes=id==='duck'?[410,300]:id==='black'?[610,780]:id==='panda'?[355,385]:[470,450];
      notes.forEach((hz,i)=>{
        const oscillator=audioCtx.createOscillator(),gain=audioCtx.createGain();
        oscillator.type=id==='duck'?'triangle':'sine';
        oscillator.frequency.setValueAtTime(hz,start+i*.075);
        oscillator.frequency.exponentialRampToValueAtTime(hz*.83,start+i*.075+.115);
        gain.gain.setValueAtTime(.0001,start+i*.075);
        gain.gain.exponentialRampToValueAtTime(.024,start+i*.075+.014);
        gain.gain.exponentialRampToValueAtTime(.0001,start+i*.075+.145);
        oscillator.connect(gain);gain.connect(audioCtx.destination);
        oscillator.start(start+i*.075);oscillator.stop(start+i*.075+.155);
      });
    } catch {}
  }

  // Show the presenter controls only when the presenter explicitly opens them.
  // Even in local preview, the panel stays hidden until the Trình diễn button is pressed.
  let showcaseOn=(new URLSearchParams(location.search).get('petshow')==='1') || window.__CN_FORCE_PETSHOW===true;
  let showcasePanel=null;
  let showcaseControl=null;
  const showcaseStatus=message=>{
    const label=showcasePanel?.querySelector('[data-cn-status]');
    if(label)label.textContent=message;
  };

  const footer = document.querySelector('footer .footer-bottom') || document.querySelector('footer');
  if(footer){
    const settings=document.createElement('span');settings.className='cn-pet-settings';
    settings.innerHTML='<span>Bốn người bạn nhỏ · V24</span><button type="button" data-cn-sound aria-pressed="false">Âm: tắt</button><button type="button" data-cn-hide aria-pressed="false">Ẩn thú</button><button type="button" data-cn-show aria-pressed="false">Trình diễn</button>';
    footer.append(settings);
    settings.querySelector('[data-cn-sound]').addEventListener('click',e=>{
      muted=!muted;e.currentTarget.textContent=muted?'Âm: tắt':'Âm: bật';e.currentTarget.setAttribute('aria-pressed',String(!muted));if(!muted)audio('panda');
    });
    settings.querySelector('[data-cn-hide]').addEventListener('click',e=>{
      hidden=!hidden;world.classList.toggle('cn-hidden',hidden);e.currentTarget.textContent=hidden?'Hiện thú':'Ẩn thú';e.currentTarget.setAttribute('aria-pressed',String(hidden));
    });
    showcaseControl=settings.querySelector('[data-cn-show]');
    showcaseControl.addEventListener('click',()=>toggleShowcase(!showcaseOn));
  }


  // V11: animated frames derive pixel-for-pixel from the original illustrations.
  // No substitute body, no SVG character rigs, no different-looking model.
  // Compact per-direction atlases keep canvas pixels stable on mobile Chromium.
  const CN_WALK_STRIPS = {"white":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"black":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"panda":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"duck":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]};
  const walkAtlases = {};
  for (const [id,uris] of Object.entries(CN_WALK_STRIPS)) {
    walkAtlases[id]=uris.map(uri=>{const img=new Image();img.src=uri;return img;});
  }
  const WALK_ROWS = {right:0,left:1,down:2,up:3};
  const gaitIntervals={walk:138,trot:97,dash:56,sneak:174,skip:102,tiptoe:172,backstep:157};
  // V20: subtle environment response. Each puff is a small cream-colored
  // cluster of dust behind moving feet, not a cloud over content or a fixed UI.
  function maybeFootDust(p, now){
    if(hidden||prefersQuiet||document.hidden||!p.visible||p.el.dataset.motion!=='move')return;
    const gait=p.activeGait;
    const fast=gait==='dash',medium=gait==='trot'||gait==='skip';
    const minGap=fast?115:medium?210:480;
    if(now-(p.lastDustAt||0)<minGap)return;
    p.lastDustAt=now;
    if(!fast&&!medium&&Math.random()>.38)return;
    const rect=p.el.getBoundingClientRect(),mainRect=main.getBoundingClientRect();
    if(rect.width<5||rect.height<5)return;
    const dir=p.el.dataset.travel||'right';
    const px=rect.left-mainRect.left,py=rect.top-mainRect.top,s=rect.width;
    const x=px+(dir==='right'?.12:dir==='left'?.88:.50)*s;
    const y=py+(dir==='down'?.12:dir==='up'?.87:.91)*s;
    // Skip particles that would spawn over meaningful text/controls.
    const ghost={x:x-5,y:y-5,w:10,h:10};
    if(getObstacles().some(o=>overlap(ghost,o)))return;
    const puff=document.createElement('span');puff.className='cn-dust-puff';
    puff.dataset.animal=p.id;
    puff.style.left=`${x}px`;puff.style.top=`${y}px`;
    const away={left:[14,-4],right:[-14,-4],up:[3,12],down:[-3,-12]}[dir]||[-12,-4];
    const mag=fast?1.0:medium?.72:.5;
    puff.style.setProperty('--dust-x',`${(away[0]+rng(-4,4))*mag}px`);
    puff.style.setProperty('--dust-y',`${(away[1]+rng(-3,3))*mag}px`);
    puff.style.setProperty('--dust-scale',fast?'1.25':medium?'1.0':'.8');
    world.append(puff);
    setTimeout(()=>puff.remove(),700);
  }

  function drawStride(p,now=performance.now()) {
    if(p.el.dataset.motion!=='move') return;
    const row=(WALK_ROWS[p.el.dataset.travel||'down']||0);
    const atlas=walkAtlases[p.id]?.[row];
    if(!atlas?.complete||!atlas.naturalWidth){
      p.el.classList.remove('cn-gait-ready');
      p.frameTick=requestAnimationFrame(t=>drawStride(p,t));return;
    }
    p.el.classList.add('cn-gait-ready');
    const ctx=p.context,mode=p.el.dataset.travel||'down';
    const gait=p.activeGait||'walk';
    const duration=gaitIntervals[gait]||118;
    const elapsed=now-(p.cycleStart||now);
    const frame=Math.floor(elapsed/duration)%12;
    const phase=(elapsed/(duration*12))*Math.PI*2;
    const legPhase=(elapsed/duration)*Math.PI/6;
    const duck=p.id==='duck';
    const isDash=gait==='dash',isTrot=gait==='trot',quiet=gait==='sneak'||gait==='tiptoe';
    const vertical=mode==='up'||mode==='down';
    const person={white:.93,black:1.12,panda:.78,duck:1.08}[p.id]||1;
    // WALK: grounded, small side-to-side body weight, most noticeable for duck.
    // RUN: a separate gallop: greater forward pitch, lifted chest, mid-stride
    // stretch/squash and a much quicker two-beat hop. Original sprite art remains.
    const bounce=(isDash?(3.4+3.2*Math.max(0,Math.sin(legPhase*2))):
      isTrot?(1.5+2.0*Math.max(0,Math.sin(legPhase*2))):
      quiet?.25:(duck?.65:.85)+1.15*Math.max(0,Math.sin(legPhase)))*person;
    const sway=Math.sin(legPhase)*(isDash?.045:isTrot?.033:duck?.067:.025)*person*(vertical?.72:1);
    const side=Math.sin(legPhase)*(isDash?1.0:duck?2.0:1.0)*person*(vertical?.52:1);
    const stretch=isDash?(1.035+.045*Math.max(0,Math.cos(legPhase*2))):isTrot?1.012:1;
    const squash=isDash?(.91+.055*Math.max(0,Math.cos(legPhase*2))):isTrot?.978:1;
    const direction=mode==='right'?1:mode==='left'?-1:0;
    const pitch=isDash?(-direction*.09):isTrot?(-direction*.025):0;
    ctx.clearRect(0,0,128,128);
    ctx.save();
    ctx.translate(64,105);
    ctx.translate(side,-bounce);
    ctx.rotate(pitch+sway);
    ctx.scale(stretch,squash);
    ctx.drawImage(atlas,frame*128,0,128,128,-64,-105,128,128);
    ctx.restore();
    maybeFootDust(p,now);
    p.frameTick=requestAnimationFrame(t=>drawStride(p,t));
  }
  function stopStride(p){if(p.frameTick){cancelAnimationFrame(p.frameTick);p.frameTick=0;} p.el.classList.remove('cn-gait-ready');}
  function startStride(p) {
    stopStride(p);p.cycleStart ??= performance.now();
    drawStride(p);
  }


  // V23: Hanging was removed at the owner's request. No dangling sprites,
  // extra arms, or duplicated art layers exist in this version.
  function stopDangle(p){
    p.el.classList.remove('cn-dangle-ready');
    p.dangleTick=0;
  }

  const pets = information.map((info,i)=>{
    const el=document.createElement('button');el.type='button';el.className='cn-pet';el.dataset.motion='idle';el.dataset.travel='down';
    el.setAttribute('aria-label','Chơi với '+info.name);el.title='Chơi với '+info.name;
    el.innerHTML=`<span class="cn-pet-art"><img class="cn-pet-img" src="${src(info.id,info.pose)}" alt="" draggable="false"/><canvas class="cn-walk-canvas" width="128" height="128" aria-hidden="true"></canvas><span class="cn-pet-zz">z z</span></span><span class="cn-pet-speech" aria-hidden="true"></span>`;
    world.append(el);
    el.dataset.animal=info.id;
    const p={...info,el,img:el.querySelector('img'),canvas:el.querySelector('canvas'),context:el.querySelector('canvas').getContext('2d',{alpha:true}),dangleTick:0,dangleStart:0,frameTick:0,cycleStart:null,bubble:el.querySelector('.cn-pet-speech'),zone:homeKeys[i],node:null,x:0,y:0,moving:false,busy:false,visible:false,lastSay:0,task:0,poseTimeout:0,talkTimeout:0,lastMove:0,visited:[],recentActs:[],recentRoutes:[],recentGaits:[],tickTimer:0,runFrames:0,lastGait:'',scenes:0,verticalTrips:0,lastVerticalDir:'',completedTrips:0,perchVisits:0,perchReactionTimer:0,lastVerticalAt:0,lastPerchAt:0,perchUnavailableUntil:0,lastPerchScene:0,lastDustAt:0};
    el.style.setProperty('--facing',i%2?'1':'-1');
    el.addEventListener('click',e=>{
      e.stopPropagation();if(!p.visible)return;
      speak(p,choose(p.says),2000,true);audio(p.id);
      emitEffect(p,p.id==='duck'?'fluster':p.id==='panda'?'stars':'spark',4);
      if(!p.busy) performAction(p,true);
    });
    return p;
  });

  // Protected objects are actual words, form controls and illustrations — hard obstacles.
  const blockedSelector = 'h1,h2,h3,h4,p,small,label,a,button,input,textarea,select,.eyebrow,.overline,.hero-foot,.product-pills,.product-emphasis,.product-spec-head,.spec-row,.section-top,.app-note,.story-quote,.poster-label,.float-note,.lipstick,.art-envelope,.story-circle,.end-ribbon,.signal-inner > span,.cn-actual-product-gallery';
  function getObstacles(){
    const mainBounds=main.getBoundingClientRect(), ob=[];
    main.querySelectorAll(blockedSelector).forEach(el=>{
      if(el.closest('.cn-world,.cn-trail'))return;
      const r=el.getBoundingClientRect();
      if(r.width<3||r.height<3)return;
      const pad=el.matches('button,a,input,textarea,select')?9:6;
      ob.push({x:r.left-mainBounds.left-pad,y:r.top-mainBounds.top-pad,w:r.width+2*pad,h:r.height+2*pad});
    });
    return ob;
  }
  const overlap=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
  function pointClear(x,y,ob){
    const s=petSize();return x>=3&&x+s<=main.clientWidth-3&&y>=3&&y+s<=main.clientHeight-3&&!ob.some(o=>overlap({x,y,w:s,h:s},o));
  }
  // A segment may be travelled only when EVERY swept pixel of the animal is clear.
  function segmentClear(a,b,ob){
    const s=petSize();
    const swept={x:Math.min(a.x,b.x),y:Math.min(a.y,b.y),w:Math.abs(b.x-a.x)+s,h:Math.abs(b.y-a.y)+s};
    return pointClear(a.x,a.y,ob)&&pointClear(b.x,b.y,ob)&&!ob.some(o=>overlap(swept,o));
  }
  const linkNames=[['TL','TM'],['TM','TR'],['TL','ML'],['ML','BL'],['TR','MR'],['MR','BR'],['BL','BM'],['BM','BR']];
  function buildZone(def,ob){
    const sec=document.querySelector(def.sel);if(!sec)return null;
    const mainR=main.getBoundingClientRect(),r=sec.getBoundingClientRect(),s=petSize();
    const left=r.left-mainR.left,top=r.top-mainR.top;
    const W=r.width,H=r.height;
    if(W<s*3||H<s*3)return null;
    const railMargin=innerWidth<=650?3:7;
    const xl=left+railMargin,xr=left+W-s-railMargin,xc=left+(W-s)/2;
    const yt=top+17,yb=top+H-s-17,ym=top+(H-s)/2;
    const candidates={TL:{x:xl,y:yt},TM:{x:xc,y:yt},TR:{x:xr,y:yt},ML:{x:xl,y:ym},MR:{x:xr,y:ym},BL:{x:xl,y:yb},BM:{x:xc,y:yb},BR:{x:xr,y:yb}};
    const nodes={};Object.entries(candidates).forEach(([k,v])=>{if(pointClear(v.x,v.y,ob))nodes[k]=v;});
    const edges=linkNames.filter(([a,b])=>nodes[a]&&nodes[b]&&segmentClear(nodes[a],nodes[b],ob));
    const adj={};Object.keys(nodes).forEach(k=>adj[k]=[]);
    edges.forEach(([a,b])=>{adj[a].push(b);adj[b].push(a);});
    if(!sec.querySelector('.cn-habitat')){
      const habitat=document.createElement('div');habitat.className='cn-habitat';habitat.setAttribute('aria-hidden','true');habitat.dataset.wood=def.key;
      habitat.innerHTML=`<svg class="cn-twig cn-twig-a" viewBox="0 0 64 120" aria-hidden="true"><path d="M8 119 Q25 89 17 62 Q10 40 32 10" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round"/><path d="M17 62 Q34 46 49 49 M21 34 Q11 20 8 9" fill="none" stroke="currentColor" stroke-width="1.8"/><ellipse cx="34" cy="21" rx="6" ry="12" transform="rotate(37 34 21)" fill="currentColor"/><ellipse cx="45" cy="46" rx="5" ry="11" transform="rotate(69 45 46)" fill="currentColor"/><ellipse cx="12" cy="16" rx="5" ry="10" transform="rotate(-31 12 16)" fill="currentColor"/><ellipse cx="25" cy="71" rx="4" ry="10" transform="rotate(43 25 71)" fill="currentColor"/></svg>
      <svg class="cn-twig cn-twig-b" viewBox="0 0 78 72" aria-hidden="true"><path d="M1 67 Q32 61 43 42 Q56 23 75 22" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M35 49 Q31 28 41 14 M55 30 Q67 34 70 45" stroke="currentColor" stroke-width="1.7" fill="none"/><ellipse cx="41" cy="16" rx="6" ry="12" transform="rotate(15 41 16)" fill="currentColor"/><ellipse cx="70" cy="42" rx="5" ry="11" transform="rotate(-26 70 42)" fill="currentColor"/></svg>
      <span class="cn-moss cn-moss-a"></span><span class="cn-moss cn-moss-b"></span>`;
      sec.append(habitat);
    }
    let guide=sec.querySelector('.cn-trail');
    if(!guide){guide=document.createElement('div');guide.className='cn-trail';guide.setAttribute('aria-hidden','true');sec.append(guide);}
    const toLocal=pt=>({x:pt.x-left+s/2,y:pt.y-top+s*.80});
    const lines=edges.map(([a,b])=>{const A=toLocal(nodes[a]),B=toLocal(nodes[b]);return `<path d="M ${A.x.toFixed(1)} ${A.y.toFixed(1)} L ${B.x.toFixed(1)} ${B.y.toFixed(1)}"/>`;}).join('');
    const disks=Object.entries(nodes).filter(([id])=>id==='TL'||id==='TR'||id==='BL'||id==='BR').map(([k,pt])=>{const L=toLocal(pt);return `<circle cx="${L.x.toFixed(1)}" cy="${L.y.toFixed(1)}" r="3.8"/>`;}).join('');
    guide.innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W.toFixed(0)} ${H.toFixed(0)}" preserveAspectRatio="none" role="presentation"><g class="cn-trail-lines">${lines}</g><g class="cn-trail-nodes">${disks}</g></svg>`;
    return {...def,sec,left,top,width:W,height:H,nodes,adj,edges};
  }
  function nearestNode(zone,point){
    return Object.keys(zone.nodes).sort((a,b)=>Math.hypot(zone.nodes[a].x-point.x,zone.nodes[a].y-point.y)-Math.hypot(zone.nodes[b].x-point.x,zone.nodes[b].y-point.y))[0];
  }
  function findPath(zone,from,to){
    if(!zone.nodes[from]||!zone.nodes[to])return null;
    const seen=new Set([from]),queue=[[from]];
    while(queue.length){const path=queue.shift();const last=path[path.length-1];if(last===to)return path;
      (zone.adj[last]||[]).forEach(n=>{if(!seen.has(n)){seen.add(n);queue.push([...path,n]);}});
    }
    return null;
  }
  // One stable, readable silhouette per travel gait; poses for grooming, sleeping,
  // falling and shaking belong to stationary scenes, not walking-frame loops.
  const motionFrames = {
    white: {walk:[0],trot:[0],dash:[0],sneak:[0],skip:[0],tiptoe:[0],backstep:[0]},
    black: {walk:[2],trot:[1],dash:[1],sneak:[0],skip:[1],tiptoe:[2],backstep:[2]},
    panda: {walk:[0],trot:[0],dash:[0],sneak:[0],skip:[0],tiptoe:[0],backstep:[0]},
    duck: {walk:[0],trot:[3],dash:[3],sneak:[0],skip:[3],tiptoe:[0],backstep:[0]}
  };
  // Scenes are intentionally unhurried. An animal completes its little ritual
  // instead of rapidly cycling through unrelated stock poses.
  const actionSpecs = {
    white: [
      {id:'groom', parts:[['sit',0,650],['groom',2,2300],['look',0,750]],weight:3.6},
      {id:'doze', parts:[['yawn',1,1150],['sleep',4,3600],['stretch',0,1100]],weight:2.6},
      {id:'shake',parts:[['listen',0,620],['shake',3,1150],['sit',0,940]],weight:2.4},
      {id:'play',parts:[['headtilt',0,950],['hop',0,750],['look',0,950]],weight:2.4},
      {id:'wiggle',parts:[['stretch',0,920],['bum',0,1400],['look',0,700]],weight:1.7},
      {id:'curious',parts:[['sniff',0,1150],['headtilt',0,1050],['sit',0,1000]],weight:2.6},
      {id:'paws',parts:[['groom',2,1550],['groom',2,1050],['blink',0,800]],weight:2.2}
    ],
    black: [
      {id:'tail',parts:[['listen',2,940],['tailwave',2,1450],['look',2,760]],weight:3},
      {id:'clean',parts:[['sit',3,750],['groom',3,1800],['sit',2,1000]],weight:3.5},
      {id:'ambush',parts:[['peek',0,1100],['pounce',1,820],['sit',2,1350]],weight:2.6},
      {id:'stretch',parts:[['stretch',2,1150],['look',2,980]],weight:2.6},
      {id:'peek',parts:[['peek',0,1200],['look',2,1100]],weight:3},
      {id:'nap',parts:[['yawn',2,950],['sleep',4,2400],['sit',2,950]],weight:1.6}
    ],
    panda: [
      {id:'facewash',parts:[['sit',0,850],['groom',1,2200],['sit',0,1100]],weight:4},
      {id:'nap',parts:[['yawn',1,1150],['sleep',2,3500],['look',0,1050]],weight:3.4},
      {id:'hello',parts:[['look',0,1050],['tailwave',1,1650],['sit',0,950]],weight:3.1},
      {id:'roll',parts:[['wobble',0,990],['roll',3,1170],['recover',4,1150]],weight:1.5},
      {id:'balance',parts:[['rock',0,1800],['headtilt',1,1020],['sit',0,1100]],weight:2.5},
      {id:'scratch',parts:[['groom',1,1600],['headtilt',0,1030]],weight:2.5}
    ],
    duck: [
      {id:'stomp',parts:[['glare',0,700],['stomp',4,900],['shake',2,900],['sit',0,600]],weight:3.8},
      {id:'wingdance',parts:[['headtilt',1,670],['flap',3,1200],['recover',0,650]],weight:3.7},
      {id:'facewash',parts:[['sit',0,520],['groom',2,1750],['shake',2,630]],weight:3.3},
      {id:'puddle',parts:[['look',0,680],['splash',2,1250],['shake',2,900],['glare',0,550]],weight:3.6},
      {id:'buttwiggle',parts:[['peek',0,530],['bum',0,1100],['stomp',4,560]],weight:3.2},
      {id:'sulk',parts:[['glare',0,1050],['sulk',0,1800],['turnback',1,600]],weight:3.1},
      {id:'waddle',parts:[['waddle',0,1250],['flap',1,750],['sit',0,780]],weight:3.3},
      {id:'sneeze',parts:[['sniff',0,690],['shake',2,880],['startle',1,580]],weight:3.0},
      {id:'surprise',parts:[['look',0,650],['startle',1,520],['fluster',4,1050]],weight:2.8},
      {id:'spin',parts:[['headtilt',0,650],['spin',0,950],['stumble',4,750]],weight:2.4},
      {id:'nap',parts:[['yawn',1,750],['sleep',2,4700],['stretch',0,850]],weight:3.0}
    ]

  };
  const gaitSpecs = {
    white:[['walk',6.4],['trot',5.1],['dash',2.0],['skip',1.0],['tiptoe',.5]],
    black:[['walk',3.6],['trot',5.0],['dash',3.0],['sneak',1.5]],
    panda:[['walk',7],['trot',2.6],['skip',.8]],
    duck:[['walk',5.0],['trot',3.2],['dash',3.4],['skip',1.2]]
  };
  const styleRates={walk:.72,trot:1.15,dash:1.85,sneak:.46,skip:.89,tiptoe:.51,backstep:.64};
  const pace={white:145,black:166,panda:102,duck:144};
  const random=()=>Math.random();
  const recentPush=(arr,id,max=7)=>{arr.push(id);if(arr.length>max)arr.shift();};
  function weighted(options){
    let total=0;for(const item of options) total+=Math.max(0,item.weight);
    if(total<=0)return options[0];
    let threshold=random()*total;
    for(const item of options){threshold-=Math.max(0,item.weight);if(threshold<=0)return item;}
    return options[options.length-1];
  }
  function chooseGait(p,favor){
    const available=gaitSpecs[p.id].map(([id,w])=>({id,weight:w*(p.recentGaits.includes(id)?.24:1)*(id===favor?2.0:1)}));
    const gait=weighted(available).id;
    recentPush(p.recentGaits,gait,3);return gait;
  }
  function setPose(p,frame,motion='idle'){
    const data=motion==='sleep'?(p.id==='duck'?CN_DUCK_SLEEP:src(p.id,sleepFrame[p.id])):src(p.id,frame);
    if(data&&p.img.getAttribute('src')!==data)p.img.src=data;
    p.el.dataset.motion=motion;
  }
  function idle(p){
    stopDangle(p);
    stopStride(p);p.cycleStart=null;
    if(!p.el.dataset.travel) p.el.dataset.travel='down';
    p.moving=false;
    clearInterval(p.runFrames);
    p.runFrames=0;
    p.activeGait='';
    p.el.dataset.gait='';
    setPose(p,p.id==='black'?2:0,'idle');
  }
  function playPose(p,frame,motion,duration=900){
    stopDangle(p);
    stopStride(p);p.cycleStart=null;
    clearInterval(p.runFrames);
    clearTimeout(p.poseTimeout);
    setPose(p,frame,motion);
    p.poseTimeout=0;
  }
  function speak(p,text,duration=2000,force=false){
    if(!p.visible||hidden||(!force&&Date.now()-p.lastSay<14000))return;
    p.lastSay=Date.now();clearTimeout(p.talkTimeout);
    p.bubble.textContent=text;p.el.classList.add('is-talking');
    p.el.dataset.edge=p.x<85?'left':p.x>main.clientWidth-petSize()-85?'right':'';
    p.el.dataset.bubble=p.y<86?'below':'above';
    p.talkTimeout=setTimeout(()=>p.el.classList.remove('is-talking'),duration);
  }
  function place(p,pt,instantly=false){
    p.x=pt.x;p.y=pt.y;
    p.el.style.transitionDuration=instantly?'0ms':'';
    p.el.style.left=`${pt.x}px`;p.el.style.top=`${pt.y}px`;
    p.el.classList.add('cn-pet-visible');p.visible=true;
    if(instantly)requestAnimationFrame(()=>p.el.style.transitionDuration='');
  }
  const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
  function emitEffect(p,type='spark',count=3){
    if(hidden||!p.visible||prefersQuiet)return;
    const px=p.x+petSize()*.45, py=p.y+petSize()*.46;
    const kind=type==='fluster'?'!':type==='sleep'?'z':type==='stars'?'✦':'·';
    for(let i=0;i<count;i++){
      const fx=document.createElement('span');fx.className='cn-particle';fx.dataset.kind=type;
      fx.textContent=kind;fx.style.left=`${px+rng(-11,11)}px`;fx.style.top=`${py+rng(-9,9)}px`;
      fx.style.setProperty('--dx',`${Math.round(rng(-30,30))}px`);
      fx.style.setProperty('--dy',`${Math.round(rng(-28,-11))}px`);
      fx.style.setProperty('--delay',`${Math.round(i*75)}ms`);
      world.append(fx);setTimeout(()=>fx.remove(),1300+i*75);
    }
  }
  function animateStride(p,gait){
    p.activeGait=gait;
    p.el.dataset.gait=gait;
    startStride(p);
  }
  async function travel(p,point,opts={}){
    const old={x:p.x,y:p.y};const dx=point.x-old.x,dy=point.y-old.y;
    const dist=Math.hypot(dx,dy);
    if(dist<2){place(p,point);return;}
    const gait=opts.gait||chooseGait(p);
    p.moving=true;
    p.el.dataset.gait=gait;
    const facing=dx < -2?'-1':dx>2?'1':p.el.style.getPropertyValue('--facing')||'1';
    p.el.style.setProperty('--facing',gait==='backstep'?(facing==='1'?'-1':'1'):facing);
    p.el.dataset.travel=Math.abs(dy)>Math.abs(dx)?(dy>0?'down':'up'):(dx>0?'right':'left');
    p.el.dataset.motion='move';
    if (!p.frameTick) animateStride(p,gait);
    else {p.activeGait=gait;p.el.dataset.gait=gait;}
    const speed=pace[p.id]*styleRates[gait]*(opts.speedMultiplier||1);
    p.el.style.setProperty('--step-time', `${Math.round(Math.max(270,Math.min(860,440 * 128 / speed)))}ms`);
    const duration=prefersQuiet?1:Math.round(Math.max(180,dist/speed*1000));
    const easing=gait==='dash'?'cubic-bezier(.24,.01,.78,.96)':gait==='sneak'?'ease-in-out':gait==='skip'?'ease-in-out':'linear';
    p.el.style.transitionDuration=`${duration}ms, ${duration}ms, 180ms`;
    p.el.style.transitionTimingFunction=`${easing},${easing},ease`;
    p.x=point.x;p.y=point.y;
    p.el.style.left=`${p.x}px`;p.el.style.top=`${p.y}px`;
    // Foot dust is generated continuously behind the moving pet by drawStride.
    await delay(duration+45);
    // Do not reset to idle between junctions. The entire route is one scene.
    if(!opts.keepMoving){p.moving=false;if(p.visible&&!hidden)idle(p);}
  }
  async function playPart(p,part){
    const [motion,frame,duration]=part;
    if(document.hidden||hidden)return;
    playPose(p,frame,motion,duration);
    if(['fluster','splash','pounce','stumble','spin','hop'].includes(motion)&&random()<.55){
      emitEffect(p,motion==='fluster'?'fluster':motion==='splash'?'splash':'stars',2);
    }
    await delay(prefersQuiet?1:duration);
    clearTimeout(p.poseTimeout);
  }
  async function performAction(p,manual=false){
    if(p.busy||!p.visible)return false;
    p.busy=true;p.task++;
    const choices=actionSpecs[p.id].map(a=>({...a,weight:a.weight*(p.recentActs.includes(a.id)?.12:1)}));
    // Demonstrations cycle through the duck's repertoire instead of repeating randomly.
    const chosen=manual&&p.id==='duck' ? choices[((p.manualDuckActIndex=(p.manualDuckActIndex||0)+1)-1) % choices.length] : weighted(choices);
    recentPush(p.recentActs,chosen.id,5);
    for(const part of chosen.parts){
      if(hidden||document.hidden)break;
      await playPart(p,part);
    }
    if(p.id==='duck')p.lastDuckActionAt=Date.now();
    if(!p.moving)idle(p);
    p.busy=false;p.scenes++;
    return true;
  }
  function edgeDirection(a,b){
    const dx=b.x-a.x,dy=b.y-a.y;
    return Math.abs(dx)>Math.abs(dy)?(dx>0?'R':'L'):(dy>0?'D':'U');
  }
  // Real up/down paths for EVERY pet, not a rotated sideways walk. The
  // directional V11 animation atlas already contains four rows per pet.
  // Prefer a long, safe vertical edge rather than random horizontal hops.
  function verticalJourney(p,zone){
    if(!zone || !zone.nodes[p.node]) return null;
    const here=zone.nodes[p.node];
    const minRise=Math.min(105, Math.max(28, zone.height*.12));
    const goals=[];
    for(const [name,position] of Object.entries(zone.nodes)) {
      const delta=position.y-here.y;
      if(Math.abs(delta)<minRise) continue;
      const path=findPath(zone,p.node,name);
      if(!path || path.length<2) continue;
      let vertical=0,horizontal=0;
      for(let i=1;i<path.length;i++){
        const a=zone.nodes[path[i-1]],b=zone.nodes[path[i]];
        if(Math.abs(b.y-a.y)>4)vertical+=Math.abs(b.y-a.y);
        else horizontal+=Math.abs(b.x-a.x);
      }
      if(vertical<minRise)continue;
      const dir=delta>0?'down':'up';
      const preferChange=dir!==p.lastVerticalDir?1.65:1;
      const weight=Math.pow(1+vertical/Math.max(120,zone.height),2.0)*preferChange/(1+horizontal/130);
      goals.push({path,weight,aligned:horizontal<8});
    }
    const laneGoals=goals.filter(x=>x.aligned);
    const candidates=laneGoals.length?laneGoals:goals;
    const picked=candidates.length?weighted(candidates):null;
    return picked?.path || null;
  }

  function routeWalk(p,zone,style='explore'){
    const start=p.node;
    if(!start||!zone.nodes[start])return null;
    const out=[start];
    const steps=style==='sprint'?Math.floor(rng(2,5)):style==='patrol'?Math.floor(rng(4,8)):style==='hesitate'?Math.floor(rng(2,5)):Math.floor(rng(2,7));
    let previousDir='',last=null;
    for(let k=0;k<steps;k++){
      const at=out[out.length-1];const exits=zone.adj[at]||[];
      if(!exits.length)break;
      const opts=exits.map(next=>{
        const direction=edgeDirection(zone.nodes[at],zone.nodes[next]);
        const recent=p.visited.slice(-7).includes(next);
        let weight=7;
        if(next===last)weight*=.18;
        if(recent)weight*=.36;
        if(direction!==previousDir)weight*=style==='patrol'?1.8:style==='explore'?1.3:.72;
        if(style==='sprint'&&direction===previousDir)weight*=2.3;
        if(style==='hesitate'&&next===last)weight*=2.1;
        const edgeDist=Math.hypot(zone.nodes[next].x-zone.nodes[at].x,zone.nodes[next].y-zone.nodes[at].y);
        if(style==='sprint'&&edgeDist>95)weight*=1.5;
        if(direction==='U'||direction==='D') weight*=2.0;
        if((direction==='U'||direction==='D')&&p.id==='white')weight*=1.25;
        const signature=at+':'+next;
        if(p.recentRoutes.includes(signature))weight*=.30;
        return {id:next,weight};
      });
      const winner=weighted(opts);if(!winner)break;
      const next=winner.id;
      recentPush(p.recentRoutes,at+':'+next,8);
      recentPush(p.visited,next,9);
      previousDir=edgeDirection(zone.nodes[at],zone.nodes[next]);last=at;out.push(next);
    }
    return out.length>1?out:null;
  }

  // Button ledges are an occasional destination in the terrain, not an event
  // handler. Animals never follow clicks and never cover the clickable control.
  function findButtonPerch(p,zone){
    const s=petSize(), ob=getObstacles(), mainR=main.getBoundingClientRect();
    const buttons=[...zone.sec.querySelectorAll('.button-primary,.button-light,.button-link,.cn-page-link,.nav-action,#app-root button,.app-content button,.step-card a')]
      .filter(el=>!el.closest('.cn-world,.cn-habitat,.cn-trail'));
    if(!buttons.length)return null;
    const options=[];
    for(const button of buttons){
      const r=button.getBoundingClientRect();
      if(r.width<32||r.height<20)continue;
      const L=r.left-mainR.left,R=r.right-mainR.left,T=r.top-mainR.top,B=r.bottom-mainR.top;
      // A pet sits beside or just above a button, *never over the label*.
      const spots=[
        {x:R+11,y:T+(r.height-s)/2,side:'right'},
        {x:L-s-11,y:T+(r.height-s)/2,side:'left'},
        {x:R-s+3,y:T-s-12,side:'top'},
        {x:L+5,y:B+12,side:'bottom'},
        {x:R-s-5,y:B+12,side:'bottom'}
      ];
      for(const pt of spots){
        if(!pointClear(pt.x,pt.y,ob))continue;
        for(const node of Object.keys(zone.nodes)){
          const start=zone.nodes[node];
          const path=findPath(zone,p.node,node);
          if(!path)continue;
          const bend1={x:pt.x,y:start.y};
          const bend2={x:start.x,y:pt.y};
          let legs=null;
          if(segmentClear(start,bend1,ob)&&segmentClear(bend1,pt,ob))legs=[bend1,pt];
          else if(segmentClear(start,bend2,ob)&&segmentClear(bend2,pt,ob))legs=[bend2,pt];
          if(!legs)continue;
          const sideBias = pt.side==='top'?1.6:pt.side==='bottom'?1.3:1.0;
          const verticalBias = pt.y>p.y+35?1.25:1;
          options.push({node,legs,spot:pt,button,weight:sideBias*verticalBias/(1+path.length*.40+Math.hypot(start.x-pt.x,start.y-pt.y)/220)});
        }
      }
    }
    if(!options.length)return null;
    const chosen=weighted(options)||choose(options);
    return chosen;
  }
  // V23: interactions NEAR buttons only. No dangling or reaching gesture.
  // Resting, grooming and looking curious use the established original sprite frames.
  async function visitButton(p,zone,opts={}){
    if(p.busy||!p.visible||document.hidden||hidden)return false;
    const option=findButtonPerch(p,zone);
    if(!option)return false;
    if(option.node!==p.node)await followRoute(p,zone,option.node,'patrol');
    if(p.busy||document.hidden||hidden)return false;
    p.busy=true;p.task++;
    const origin={...zone.nodes[option.node]};
    const gait=chooseGait(p,'walk');
    let settled=false, onButton=null;
    const isRest=opts.pose==='rest'?true:opts.pose==='play'?false:
      (p.id==='white'||p.id==='panda'?Math.random()<.61:Math.random()<.24);
    try{
      for(let i=0;i<option.legs.length;i++){
        const point=option.legs[i];
        if(hidden||document.hidden)return false;
        if(Math.hypot(point.x-p.x,point.y-p.y)>2)
          await travel(p,point,{gait,keepMoving:i<option.legs.length-1});
      }
      if(hidden||document.hidden)return false;
      p.moving=false;idle(p);
      p.el.dataset.perch=isRest?'rest':'near';
      p.el.dataset.perchSide=option.spot.side;
      settled=true;
      p.perchVisits++;p.lastPerchAt=Date.now();p.lastPerchScene=p.scenes;
      // React locally when the nearby button is touched; don't intercept clicks.
      onButton=()=>{
        if(!['rest','near'].includes(p.el.dataset.perch))return;
        p.el.classList.remove('cn-perch-alert');
        void p.el.offsetWidth;
        p.el.classList.add('cn-perch-alert');
        clearTimeout(p.perchReactionTimer);
        p.perchReactionTimer=setTimeout(()=>p.el.classList.remove('cn-perch-alert'),620);
      };
      for(const event of ['pointerenter','focus','pointerdown'])
        option.button.addEventListener(event,onButton,{passive:true});
      if(isRest){
        playPose(p,sleepFrame[p.id],'sleep');
        await delay(prefersQuiet?1:(opts.holdMs||Math.round(rng(4300,5900))));
      }else{
        const routines={
          white:[['sit',0,700],['groom',2,1750],['blink',0,1150]],
          black:[['peek',0,950],['groom',3,1520],['sit',2,1250]],
          panda:[['sit',0,1000],['groom',1,1750],['look',0,1180]],
          duck:[['glare',0,980],['shake',2,980],['groom',0,1550]]
        };
        for(const part of routines[p.id]){
          if(hidden||document.hidden)break;
          await playPart(p,part);
        }
        if(!hidden&&!document.hidden){
          playPose(p,p.id==='black'?2:0,'sit');
          await delay(prefersQuiet?1:Math.max(650,(opts.holdMs||4600)-3550));
        }
      }
    }finally{
      if(onButton)for(const event of ['pointerenter','focus','pointerdown'])
        option.button.removeEventListener(event,onButton);
      clearTimeout(p.perchReactionTimer);
      p.el.classList.remove('cn-perch-alert');
      p.el.dataset.perch='';p.el.dataset.perchSide='';
      if(!hidden&&!document.hidden&&settled){
        const reverse=[...option.legs].reverse();
        reverse.shift();reverse.push(origin);
        for(let i=0;i<reverse.length;i++){
          const pt=reverse[i];
          if(Math.hypot(pt.x-p.x,pt.y-p.y)>2)
            await travel(p,pt,{gait:'walk',keepMoving:i<reverse.length-1});
        }
      }
      p.node=option.node;
      p.busy=false;p.scenes++;
      if(!p.moving)idle(p);
    }
    return true;
  }

  async function followRoute(p,zone,to=null,scene='explore'){
    if(p.busy||!zone||!p.visible)return false;
    const promoteVertical=!to && (scene==='vertical' || p.completedTrips===0 || p.completedTrips%3===0 || Math.random()<.55);
    let path=to?findPath(zone,p.node,to):
      (promoteVertical?verticalJourney(p,zone):null) || routeWalk(p,zone,scene);
    if(!path||path.length<2)return false;
    const verticalDistance=path.slice(1).reduce((total,name,i)=>total+Math.abs(zone.nodes[name].y-zone.nodes[path[i]].y),0);
    const netY=zone.nodes[path[path.length-1]].y-zone.nodes[path[0]].y;
    p.busy=true;p.task++;
    const task=p.task;
    const travelGait=scene==='sprint'?'dash':chooseGait(p,scene==='patrol'?'trot':p.id==='white'?'trot':'walk');
    if(p.id==='duck'&&travelGait==='dash')p.lastDuckDashAt=Date.now();
    for(let i=1;i<path.length;i++){
      if(task!==p.task||hidden||document.hidden){idle(p);break;}
      const target=zone.nodes[path[i]];
      if(!target)break;
      await travel(p,target,{gait:travelGait,keepMoving:i<path.length-1});p.node=path[i];

    }
    p.busy=false;p.lastMove=Date.now();p.scenes++;p.completedTrips++;
    if(verticalDistance>60){p.verticalTrips++;p.lastVerticalAt=Date.now();if(Math.abs(netY)>30)p.lastVerticalDir=netY>0?'down':'up';}
    return true;
  }
  function setGeometry(initial=false){
    // Visual order is bound to the page, not to the viewport or current scroll.
    const obstacles=getObstacles();
    for(const def of sections){const zone=buildZone(def,obstacles);if(zone)zoneMap.set(def.key,zone);}
    pets.forEach((p,i)=>{
      const zone=zoneMap.get(p.zone);if(!zone||!Object.keys(zone.nodes).length)return;
      // Initialize into a safe corner; preserve occupants across resize and content changes.
      if(initial||!p.visible){
        const preferred=['ML','TR','BR','BL'][i];
        p.node=zone.nodes[preferred]?preferred:Object.keys(zone.nodes)[0];
        place(p,zone.nodes[p.node],true);idle(p);
      } else if(!p.busy){
        const dest=zone.nodes[p.node]?p.node:nearestNode(zone,p);
        p.node=dest;place(p,zone.nodes[dest],true);
      }
    });
  }
  function schedulePet(p,delayMs){
    clearTimeout(p.tickTimer);
    if(showcaseOn)return;
    p.tickTimer=setTimeout(()=>petTick(p),delayMs);
  }
  // V13: Daily-life pacing. Vertical travel and button visits are planned
  // activities, not rare outcomes of unrelated random action weights.
  async function petTick(p){
    if(prefersQuiet || showcaseOn)return;
    if(document.hidden||hidden||!p.visible){schedulePet(p,rng(1200,2600));return;}
    if(p.busy){schedulePet(p,rng(650,1450));return;}
    const zone=zoneMap.get(p.zone);
    if(!zone){schedulePet(p,2000);return;}
    const now=Date.now();
    const canTryButton=!!zone.sec.querySelector('.button-primary,.button-light,.button-link,.cn-page-link,#app-root button,.app-content button,.step-card a')
      && now >= p.perchUnavailableUntil;
    const verticalDue=p.verticalTrips===0 || (now-p.lastVerticalAt>17000);
    const buttonDue=canTryButton && (p.perchVisits===0 || now-p.lastPerchAt>23000);
    const duckActionDue=p.id==='duck' && (!p.lastDuckActionAt || now-p.lastDuckActionAt>19000);
    const duckDashDue=p.id==='duck' && p.completedTrips>=2 && (!p.lastDuckDashAt || now-p.lastDuckDashAt>30000);
    // Each animal has a reliable first vertical trip, then a button visit.
    // When both are overdue, alternate the priority so neither is starved.
    let choice;
    if(p.verticalTrips===0)choice='vertical';
    else if(duckActionDue && (!buttonDue || p.scenes%2===1))choice='action';
    else if(duckDashDue && (!verticalDue || p.scenes%3===0))choice='sprint';
    else if(buttonDue && (!verticalDue || p.scenes%2===0))choice='perch';
    else if(verticalDue)choice='vertical';
    else choice=weighted([
      {id:'vertical',weight:5.4},
      {id:'perch',weight:canTryButton && now-p.lastPerchAt>11000 ? 5.0 : 1.3},
      {id:'explore',weight:p.id==='black'?3.0:2.1},
      {id:'patrol',weight:1.6},
      {id:'sprint',weight:p.id==='duck'?3.4:p.id==='black'?1.5:.5},
      {id:'action',weight:p.id==='duck'?5.5:p.id==='panda'||p.id==='white'?3.4:2.6},
      {id:'quiet',weight:1.4}
    ]).id;
    try {
      if(choice==='perch'){
        if(!await visitButton(p,zone)){
          // A section may have a button but no safe route to its edge.
          // Remember that briefly; don't get stuck repeatedly trying it.
          p.perchUnavailableUntil=Date.now()+18000;
          await followRoute(p,zone,null,'vertical');
        }
      } else if(choice==='vertical')await followRoute(p,zone,null,'vertical');
      else if(choice==='action')await performAction(p);
      else if(choice!=='quiet')await followRoute(p,zone,null,choice);
    } catch(err) { p.busy=false;idle(p); }
    if(!p.busy&&random()<.045&&p.scenes%4===0)speak(p,choose(p.says),1600);
    // Rest between complete journeys; do not switch animation mid-route.
    schedulePet(p,rng(p.id==='black'?950:1300,p.id==='panda'?2900:2500));
  }
  function allObstacles(){return getObstacles();}
  async function migrate(){
    if(prefersQuiet||showcaseOn||document.hidden||hidden||globalBusy||Math.random()>.55)return;
    const pairs=[];
    for(const p of pets){
      if(p.busy||!p.visible)continue;
      const i=sections.findIndex(z=>z.key===p.zone);
      for(const nextI of [i-1,i+1]){
        if(nextI<0||nextI>=sections.length)continue;
        const target=sections[nextI].key;
        if(pets.some(other=>other!==p&&other.zone===target))continue;
        const a=zoneMap.get(p.zone),b=zoneMap.get(target);
        if(!a||!b)continue;
        const down=nextI>i;
        for(const side of ['right','left']){
          const exit=down?(side==='right'?'BR':'BL'):(side==='right'?'TR':'TL');
          const entry=down?(side==='right'?'TR':'TL'):(side==='right'?'BR':'BL');
          if(!a.nodes[exit]||!b.nodes[entry]||!findPath(a,p.node,exit))continue;
          const from=a.nodes[exit],to=b.nodes[entry];
          const obstacles=allObstacles();
          const bridges=[
            [from,{x:to.x,y:from.y},to],
            [from,{x:from.x,y:to.y},to]
          ];
          let bridge=bridges.find(pts=>pts.slice(1).every((pt,j)=>segmentClear(pts[j],pt,obstacles)));
          let tunnel=false;
          // A dark separating banner is an *underpass*. Keep the full
          // continuous journey, but fade behind it instead of crossing text.
          if(!bridge&&[p.zone,target].includes('hero')&&[p.zone,target].includes('product')&&Math.abs(from.x-to.x)<2){
            bridge=[from,to];tunnel=true;
          }
          if(!bridge)continue;
          pairs.push({p,a,b,exit,entry,target,from,to,bridge,tunnel});
        }
      }
    }
    if(!pairs.length)return;
    const m=choose(pairs);globalBusy=true;
    await followRoute(m.p,m.a,m.exit,'patrol');
    m.p.busy=true;
    if(m.tunnel)m.p.el.classList.add('cn-underpass');
    for(const point of m.bridge.slice(1)){if(Math.hypot(point.x-m.p.x,point.y-m.p.y)>2)await travel(m.p,point,{gait:'walk',keepMoving:point!==m.to});}
    if(m.tunnel)m.p.el.classList.remove('cn-underpass');
    m.p.busy=false;m.p.zone=m.target;m.p.node=m.entry;
    if(Math.random()<.55)await playPart(m.p,m.p.id==='duck'?['glare',1,850]:m.p.id==='panda'?['wobble',1,900]:['look',0,600]);
    globalBusy=false;
  }
  async function friendScene(){
    if(prefersQuiet||showcaseOn||hidden||document.hidden||Date.now()-lastFriendScene<16500||globalBusy)return;
    const sorted=pets.filter(p=>p.visible&&!p.busy).sort((a,b)=>sections.findIndex(z=>z.key===a.zone)-sections.findIndex(z=>z.key===b.zone));
    if(sorted.length<2)return;
    const pairs=[];
    for(let i=0;i<sorted.length-1;i++){
      const a=sorted[i],b=sorted[i+1],za=zoneMap.get(a.zone),zb=zoneMap.get(b.zone);
      if(!za||!zb)continue;
      const ia=sections.findIndex(z=>z.key===a.zone),ib=sections.findIndex(z=>z.key===b.zone);
      if(ib!==ia+1||!za.nodes.BR||!zb.nodes.TR)continue;
      if(!findPath(za,a.node,'BR')||!findPath(zb,b.node,'TR'))continue;
      pairs.push({a,b,za,zb});
    }
    if(!pairs.length)return;
    lastFriendScene=Date.now();
    const m=choose(pairs);
    await Promise.all([followRoute(m.a,m.za,'BR','sprint'),followRoute(m.b,m.zb,'TR','patrol')]);
    if(hidden||document.hidden)return;
    const duck=[m.a,m.b].find(p=>p.id==='duck');
    const black=[m.a,m.b].find(p=>p.id==='black');
    const panda=[m.a,m.b].find(p=>p.id==='panda');
    const white=[m.a,m.b].find(p=>p.id==='white');
    if(duck){
      speak(duck,choose(['Ê! Né ra!','Đừng chọc tui!','Tui không có giận!']),1500,true);
      emitEffect(duck,'fluster',3);
      await Promise.all([playPart(duck,['fluster',1,1000]),playPart(duck===m.a?m.b:m.a,['startle',3,900])]);
    } else if(black&&white){
      speak(white,'Cho tui ngủ với…',1750,true);
      await Promise.all([playPart(white,['sleep',1,1800]),playPart(black,['pounce',3,900])]);
      await playPart(white,['startle',2,640]);
    } else if(panda){
      speak(panda,'Úi, vấp rồi!',1600,true);
      emitEffect(panda,'stars',2);
      await Promise.all([playPart(panda,['stumble',3,890]),playPart(panda===m.a?m.b:m.a,['look',0,900])]);
    } else {
      await Promise.all([playPart(m.a,['headtilt',0,800]),playPart(m.b,['hop',3,800])]);
    }
  }
  if(new URLSearchParams(location.search).has('cnDebug')) {
    window.__cacaoMascotDebug = { pets, zoneMap, travel, findButtonPerch, visitButton, getObstacles, pointClear, petSize, setGeometry, segmentClear, verticalJourney, followRoute, petTick };
  }

  // V14 presentation controls. This is a *presenter-only* interface; the four
  // animals remain anchored in document coordinates, not viewport coordinates.
  function toggleShowcase(active){
    showcaseOn=!!active;
    if(!showcasePanel)return;
    showcasePanel.hidden=!showcaseOn;
    showcaseControl?.setAttribute('aria-pressed',String(showcaseOn));
    showcaseStatus(showcaseOn?'Chọn một con và một hành động.':'');
    pets.forEach(p=>{
      clearTimeout(p.tickTimer);
      if(!showcaseOn&&!prefersQuiet&&!p.busy)schedulePet(p,1100+rng(0,850));
    });
  }
  function closestPetToViewport(){
    const mid=innerHeight*.45;
    return pets.filter(p=>p.visible).sort((a,b)=>{
      const ra=a.el.getBoundingClientRect(),rb=b.el.getBoundingClientRect();
      const score=r=>Math.abs((r.top+r.bottom)*.5-mid) + (r.bottom<0||r.top>innerHeight?300:0);
      return score(ra)-score(rb);
    })[0]||pets[0];
  }
  function selectShowcasePet(){
    const choice=showcasePanel?.querySelector('[data-cn-pet]')?.value||'auto';
    return pets.find(p=>p.id===choice)||closestPetToViewport();
  }
  function pathForVerticalCommand(p,zone,sign){
    const start=p.node;
    if(!zone.nodes[start])return null;
    const all=Object.entries(zone.nodes);
    const directed=all.filter(([n,pt])=>sign*(pt.y-zone.nodes[start].y)>38)
      .map(([n,pt])=>{
        const path=findPath(zone,start,n);
        if(!path)return null;
        let length=0;for(let i=1;i<path.length;i++)length+=Math.hypot(zone.nodes[path[i]].x-zone.nodes[path[i-1]].x,zone.nodes[path[i]].y-zone.nodes[path[i-1]].y);
        return {path,score:Math.abs(pt.y-zone.nodes[start].y)*2-length*.48};
      }).filter(Boolean).sort((a,b)=>b.score-a.score);
    if(directed.length)return directed[0].path;
    // At the edge: walk to the opposite end before taking the requested
    // direction, never teleport to the start of a track.
    const opposite=all.filter(([n,pt])=>sign*(pt.y-zone.nodes[start].y)<-38)
      .map(([n,pt])=>({n,dist:Math.abs(pt.y-zone.nodes[start].y)})).sort((a,b)=>b.dist-a.dist);
    for(const item of opposite){
      const first=findPath(zone,start,item.n);
      const next=all.filter(([n,pt])=>sign*(pt.y-zone.nodes[item.n].y)>38)
        .sort((a,b)=>Math.abs(b[1].y-zone.nodes[item.n].y)-Math.abs(a[1].y-zone.nodes[item.n].y));
      for(const [dest] of next){const second=findPath(zone,item.n,dest);if(first&&second)return first.concat(second.slice(1));}
    }
    return null;
  }
  function pathForSprint(p,zone){
    const start=p.node; if(!zone.nodes[start])return null;
    const options=Object.keys(zone.nodes).map(n=>{
      const path=findPath(zone,start,n);if(!path||path.length<2)return null;
      const dx=Math.abs(zone.nodes[n].x-zone.nodes[start].x);
      const dy=Math.abs(zone.nodes[n].y-zone.nodes[start].y);
      return {path,score:dx*1.4+dy*.5};
    }).filter(Boolean).sort((a,b)=>b.score-a.score);
    return options[0]?.path||null;
  }
  async function showcasePath(p,zone,path,gait){
    if(!path||path.length<2)return false;
    if(p.busy)return false;
    p.busy=true;p.task++;const token=p.task;
    try {
      for(let i=1;i<path.length;i++){
        if(token!==p.task || hidden || document.hidden)return false;
        const pt=zone.nodes[path[i]];if(!pt)return false;
        await travel(p,pt,{gait,keepMoving:i<path.length-1});
        if(token!==p.task)return false;
        p.node=path[i];
      }
      p.scenes++;p.completedTrips++;
      return true;
    } finally {
      if(token===p.task){p.busy=false;idle(p);}
    }
  }
  async function showcaseCommand(action){
    if(!showcaseOn)return;
    const p=selectShowcasePet();
    if(!p||!p.visible){showcaseStatus('Chưa tải xong linh vật.');return;}
    const zone=zoneMap.get(p.zone);
    if(!zone){showcaseStatus('Khu vực chưa sẵn sàng.');return;}
    if(hidden){hidden=false;world.classList.remove('cn-hidden');const toggle=document.querySelector('[data-cn-hide]');if(toggle){toggle.textContent='Ẩn thú';toggle.setAttribute('aria-pressed','false');}}
    if(p.busy){
      // Do not overlap scenes or teleport a character mid-walk.
      showcaseStatus(`${p.name} đang làm nốt động tác trước…`);
      if(!p.showcaseQueueRunning){
        p.showcaseQueueRunning=true;
        for(let tries=0;tries<150&&p.busy&&showcaseOn;tries++)await delay(80);
        p.showcaseQueueRunning=false;
      }
      if(!showcaseOn||p.busy){showcaseStatus('Chạm lại sau khi con vật dừng.');return;}
    }
    const view=zone.sec.getBoundingClientRect();
    if(view.bottom<80 || view.top>innerHeight-90){
      zone.sec.scrollIntoView({behavior:'smooth',block:'start'});
      await delay(240);
    }
    showcaseStatus(`${p.name}: ${action==='down'?'đi xuống':action==='up'?'đi lên':action==='dash'?'chạy nhanh':action==='walk'?'đi thường':action==='play'?'chơi cạnh nút':action==='rest'?'ngủ cạnh nút':action==='sleepnow'?'ngủ ngay':'làm trò'}…`);
    try{
      let ok=false;
      if(action==='down'||action==='up')ok=await showcasePath(p,zone,pathForVerticalCommand(p,zone,action==='down'?1:-1),'trot');
      else if(action==='dash'||action==='walk')ok=await showcasePath(p,zone,pathForSprint(p,zone),action==='dash'?'dash':'walk');
      else if(action==='play'||action==='rest')ok=await visitButton(p,zone,{pose:action,holdMs:5300});
      else if(action==='sleepnow'){
        p.busy=true;playPose(p,sleepFrame[p.id],'sleep');
        await delay(prefersQuiet?80:4900);idle(p);p.busy=false;ok=true;
      }
      else if(action==='act')ok=await performAction(p,true);
      showcaseStatus(ok ? `${p.name} đã diễn xong.` : `Không có lối an toàn cho ${p.name} ở khu này.`);
    } catch(err){showcaseStatus('Không thực hiện được động tác; bạn thử lại.');if(!p.moving)idle(p);p.busy=false;}
    finally { if(!showcaseOn && !prefersQuiet) schedulePet(p,1100+rng(0,750)); }
  }
  function makeShowcasePanel(){
    showcasePanel=document.createElement('aside');
    showcasePanel.className='cn-showcase';
    showcasePanel.setAttribute('aria-label','Điều khiển trình diễn 4 linh vật');
    showcasePanel.hidden=!showcaseOn;
    showcasePanel.innerHTML=`<div class="cn-showcase-top"><strong>Trình diễn linh vật</strong><button type="button" data-cn-close title="Đóng điều khiển" aria-label="Đóng trình diễn">×</button></div>
      <label class="cn-showcase-label" for="cn-showcase-select">Chọn linh vật</label>
      <select id="cn-showcase-select" data-cn-pet><option value="auto">Con đang ở màn hình</option><option value="white">Mèo trắng</option><option value="black">Mèo đen</option><option value="panda">Gấu trúc</option><option value="duck">Vịt vàng</option></select>
      <div class="cn-showcase-grid">
       <button type="button" data-cn-act="down">↓ Đi xuống</button><button type="button" data-cn-act="up">↑ Đi lên</button>
       <button type="button" data-cn-act="dash">→ Chạy nhanh</button><button type="button" data-cn-act="play">✳ Chơi gần nút</button>
       <button type="button" data-cn-act="rest">☾ Ngủ gần nút</button><button type="button" data-cn-act="act">✳ Hành động vui</button>
       <button type="button" data-cn-act="sleepnow">☾ Ngủ ngay</button><button type="button" data-cn-act="walk">→ Đi thường</button>
      </div><p class="cn-showcase-status" aria-live="polite" data-cn-status>Chọn một con và một hành động.</p>`;
    document.body.append(showcasePanel);
    showcasePanel.querySelector('[data-cn-close]').addEventListener('click',()=>toggleShowcase(false));
    showcasePanel.querySelectorAll('[data-cn-act]').forEach(button=>button.addEventListener('click',()=>void showcaseCommand(button.dataset.cnAct)));
    document.addEventListener('keydown',event=>{
      if(event.altKey&&event.key.toLowerCase()==='d'&&!event.repeat){event.preventDefault();toggleShowcase(!showcaseOn);return;}
      if(!showcaseOn||event.altKey||event.ctrlKey||event.metaKey||/input|textarea|select/i.test(document.activeElement?.tagName||''))return;
      const action={1:'down',2:'up',3:'dash',4:'play',5:'rest',6:'act'}[event.key];
      if(action){event.preventDefault();void showcaseCommand(action);}
    });
    showcaseControl?.setAttribute('aria-pressed',String(showcaseOn));
  }
  makeShowcasePanel();

  // Touching an animal is a deliberate interaction; clicking ordinary page controls does not summon it.
  requestAnimationFrame(()=>{
    setGeometry(true);
    if(!prefersQuiet){
      pets.forEach((p,i)=>schedulePet(p,2600+i*1050));
      setInterval(migrate,26000);
      setInterval(friendScene,28000);
    }
  });
  const observer = new ResizeObserver(()=>{
    clearTimeout(geometryTimer);
    geometryTimer=setTimeout(()=>{if(!pets.some(p=>p.busy))setGeometry(false);else pendingGeometry=true;},280);
  });
  sections.forEach(def=>{const el=document.querySelector(def.sel);if(el){el.classList.add('cn-environment');observer.observe(el);}});
  // Deliberately NO scroll listener. All paths are page-relative and exist before the visitor reaches them.
  setInterval(()=>{if(pendingGeometry&&!pets.some(p=>p.busy)){pendingGeometry=false;setGeometry(false);}},2300);
  window.addEventListener('resize',()=>{
    clearTimeout(geometryTimer);
    geometryTimer=setTimeout(()=>{if(!pets.some(p=>p.busy))setGeometry(false);else pendingGeometry=true;},260);
  });
})();
